<?php
declare(strict_types=1);
$customers=[];
try{$st=$dbh->prepare("SELECT MIN(id) AS id,MAX(buyer_name) AS name,buyer_email AS email,MAX(buyer_phone) AS phone,COUNT(*) AS orders_count,SUM(total_cents) AS spent_cents,MIN(created_at) AS joined_at,MAX(created_at) AS last_order_at,MAX(currency) AS currency FROM org_orders WHERE org_id=:org AND buyer_email IS NOT NULL AND TRIM(buyer_email)<>'' GROUP BY LOWER(TRIM(buyer_email)) ORDER BY last_order_at DESC LIMIT 500");$st->execute([':org'=>(int)$orgId]);$customers=$st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){}
$total=count($customers);$new=0;$repeat=0;$spent=0;foreach($customers as $c){$joined=strtotime((string)$c['joined_at'])?:0;if($joined>=time()-7*86400)$new++;if((int)$c['orders_count']>1)$repeat++;$spent+=(int)$c['spent_cents'];}$orders=array_sum(array_map(static fn($c)=>(int)$c['orders_count'],$customers));$avg=$orders?(int)round($spent/$orders):0;
?>
<style>.cus-action-menu{display:none;position:fixed;z-index:9999;width:205px;padding:6px;background:var(--ch-surface,#fff);border:1px solid #dce5f1;border-radius:10px;box-shadow:0 14px 34px rgba(15,23,42,.18)}.cus-action-menu.open{display:block}.cus-action-menu a,.cus-action-menu button{display:flex;align-items:center;gap:9px;width:100%;padding:8px 9px;border:0;border-radius:7px;background:transparent;color:#10204a;text-decoration:none;text-align:left;font-size:11px;font-weight:700;cursor:pointer}.cus-action-menu a:hover,.cus-action-menu button:hover{background:#f5f8ff}.cus-action-menu i{width:15px;text-align:center}.cus-action-sep{height:1px;background:#e2e8f0;margin:5px -6px}.cus-action-menu .danger{color:#dc2626}</style>
<div class="cus-action-menu" id="cusActionMenu" role="menu"></div>
<script>
document.addEventListener('click',function(e){
 var customerCell=e.target.closest('.cus-row td:first-child');if(customerCell){var m=customerCell.innerText.trim().match(/(\d+)$/);if(m){window.location.href='customer_detail.php?id='+parseInt(m[1],10);return;}}
 var menu=document.getElementById('cusActionMenu'),btn=e.target.closest('.cus-more');if(!menu)return;
 if(btn){e.preventDefault();e.stopPropagation();var row=btn.closest('.cus-row'),c=row.cells,id=c[0].innerText.trim(),name=c[1].innerText.trim(),email=c[2].innerText.trim(),q=encodeURIComponent(email||name);menu.dataset.id=id;menu.innerHTML='<a href="crm_contacts.php?q='+q+'"><i class="fa fa-eye"></i> View Customer</a><a href="sales_management.php#orders"><i class="fa fa-shopping-bag"></i> View Orders</a><a href="crm_contacts.php?q='+q+'"><i class="fa fa-user-plus"></i> Customer Profile</a><div class="cus-action-sep"></div><a href="crm_contacts.php?q='+q+'"><i class="fa fa-pencil"></i> Edit Customer</a><a href="crm_contacts.php?q='+q+'"><i class="fa fa-sticky-note-o"></i> Add Note</a><a href="crm_contacts.php?q='+q+'"><i class="fa fa-users"></i> Add to Group</a><div class="cus-action-sep"></div><button data-cus-row-export><i class="fa fa-download"></i> Download Statement</button><button data-cus-row-export><i class="fa fa-file-o"></i> Export Customer</button><div class="cus-action-sep"></div><a class="danger" href="crm_contacts.php?q='+q+'"><i class="fa fa-trash-o"></i> Delete Customer</a>';menu.classList.add('open');var b=btn.getBoundingClientRect(),left=Math.min(innerWidth-213,b.right-205),top=b.bottom+5;if(top+menu.offsetHeight>innerHeight-8)top=Math.max(8,b.top-menu.offsetHeight-5);menu.style.left=Math.max(8,left)+'px';menu.style.top=top+'px';return;}
 var exp=e.target.closest('[data-cus-row-export]');if(exp){e.preventDefault();var rows=[].slice.call(document.querySelectorAll('.cus-row')),row=rows.find(function(r){return r.cells[0].innerText.trim()===menu.dataset.id});if(row){var cells=[].slice.call(row.cells,0,9),csv='Customer ID,Customer,Email,Phone,Orders,Spend,Average,Status,Joined\n'+cells.map(function(c){return '"'+c.innerText.trim().replace(/"/g,'""')+'"'}).join(','),blob=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=menu.dataset.id+'.csv';a.click();setTimeout(function(){URL.revokeObjectURL(a.href)},500)}menu.classList.remove('open');return;}
 if(!e.target.closest('#cusActionMenu'))menu.classList.remove('open');
});
</script>
<style>
.cus{--t:#10204a;--m:#657292;--b:#dce5f1;color:var(--t);height:calc(100vh - var(--org-header-h,48px) - 24px);display:flex;flex-direction:column;gap:10px;overflow:hidden}.cus *{box-sizing:border-box}.cus a{text-decoration:none}.cus-top{display:flex;justify-content:flex-end}.cus-btn,.cus-filter select,.cus-filter button{height:34px;border:1px solid var(--b);border-radius:8px;background:var(--ch-surface,#fff);color:var(--t);padding:0 12px;font-size:11px;font-weight:800}.cus-kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.cus-kpi{height:98px;border:1px solid var(--b);border-radius:11px;background:var(--ch-surface,#fff);padding:12px;display:flex;align-items:center;gap:11px}.cus-ico{width:39px;height:39px;flex:0 0 auto;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#4f46e5;color:#fff;font-size:18px}.cus-ico.orange{background:#f59e0b}.cus-ico.green{background:#059669}.cus-ico.blue{background:#155eef}.cus-ico.red{background:#ef233c}.cus-kpi small{display:block;color:var(--m);font-weight:700;font-size:10px}.cus-kpi strong{display:block;font-size:20px}.cus-trend{font-size:9px;color:#159c68}.cus-filter{display:flex;gap:8px}.cus-search{height:34px;border:1px solid var(--b);border-radius:8px;background:var(--ch-surface,#fff);display:flex;align-items:center;gap:8px;padding:0 11px;flex:1}.cus-search input{border:0;outline:0;width:100%;font-size:11px}.cus-card{flex:1;min-height:0;border:1px solid var(--b);border-radius:11px;background:var(--ch-surface,#fff);display:flex;flex-direction:column;overflow:hidden}.cus-table-wrap{flex:1;min-height:0;overflow:hidden}.cus-table{width:100%;border-collapse:collapse}.cus-table th,.cus-table td{padding:9px 11px;border-bottom:1px solid var(--b);text-align:left;font-size:10px}.cus-table th{color:var(--m);background:var(--ch-surface,#fbfcfe);font-size:9px}.cus-id{color:#155eef;font-weight:900}.cus-person{display:flex;align-items:center;gap:8px;font-weight:800}.cus-avatar{width:29px;height:29px;border-radius:50%;background:#e0e7ff;color:#4338ca;display:flex;align-items:center;justify-content:center;font-weight:900}.cus-status{display:inline-flex;padding:4px 8px;border-radius:999px;background:#dcfce7;color:#15803d;font-size:9px;font-weight:900}.cus-status.inactive{background:#f1f5f9;color:#64748b}.cus-more{width:29px;height:29px;border:1px solid var(--b);background:var(--ch-surface,#fff);border-radius:7px;color:#10204a}.cus-foot{display:flex;justify-content:space-between;align-items:center;padding:9px 12px;font-size:10px;color:var(--m)}.cus-pages{display:flex;gap:5px}.cus-pages button{width:29px;height:29px;border:1px solid var(--b);border-radius:7px;background:var(--ch-surface,#fff)}.cus-pages button.on{background:#155eef;color:#fff}@media(min-width:901px){html[data-sales-active-view="customers"],html[data-sales-active-view="customers"] body.org-app,html[data-sales-active-view="customers"] body.org-app .sh-mainpanel,html[data-sales-active-view="customers"] body.org-app .sh-pagebody{overflow:hidden!important}}@media(max-width:900px){.cus{height:auto;overflow:visible}.cus-kpis{grid-template-columns:1fr 1fr}.cus-filter{flex-wrap:wrap}.cus-table-wrap{overflow:auto}}
</style>
<div class="cus" id="customersRoot"><div class="cus-top"><button class="cus-btn" id="cusExport"><i class="fa fa-download"></i> Export</button></div><section class="cus-kpis"><div class="cus-kpi"><span class="cus-ico"><i class="fa fa-users"></i></span><div><small>Total Customers</small><strong><?=$total?></strong><span class="cus-trend">All buyers</span></div></div><div class="cus-kpi"><span class="cus-ico orange"><i class="fa fa-user-plus"></i></span><div><small>New Customers</small><strong><?=$new?></strong><span class="cus-trend">Last 7 days</span></div></div><div class="cus-kpi"><span class="cus-ico green"><i class="fa fa-shopping-bag"></i></span><div><small>Repeat Customers</small><strong><?=$repeat?></strong><span class="cus-trend">2+ orders</span></div></div><div class="cus-kpi"><span class="cus-ico blue"><i class="fa fa-usd"></i></span><div><small>Total Spend</small><strong><?=org_ecommerce_h(org_sales_money($spent))?></strong><span class="cus-trend">Customer revenue</span></div></div><div class="cus-kpi"><span class="cus-ico red"><i class="fa fa-shopping-cart"></i></span><div><small>Avg. Order Value</small><strong><?=org_ecommerce_h(org_sales_money($avg))?></strong><span class="cus-trend">Across <?=$orders?> orders</span></div></div></section>
<div class="cus-filter"><label class="cus-search"><i class="fa fa-search"></i><input id="cusSearch" type="search" placeholder="Search by name, email, phone or customer ID..."></label><select id="cusStatus"><option value="">All Status</option><option value="active">Active</option><option value="inactive">Inactive</option></select><select id="cusGroup"><option value="">All Groups</option><option value="repeat">Repeat Customers</option><option value="new">New Customers</option></select><button id="cusReset"><i class="fa fa-refresh"></i> Reset</button></div>
<section class="cus-card"><div class="cus-table-wrap"><table class="cus-table"><thead><tr><th>Customer ID</th><th>Customer</th><th>Email</th><th>Phone</th><th>Total Orders</th><th>Total Spend</th><th>Avg. Order Value</th><th>Status</th><th>Joined Date</th><th>Actions</th></tr></thead><tbody><?php if(!$customers):?><tr><td colspan="10" style="text-align:center;padding:25px;color:#657292">No customers yet.</td></tr><?php endif;?><?php foreach($customers as $c):$cid='CUST-'.str_pad((string)(int)$c['id'],7,'0',STR_PAD_LEFT);$name=trim((string)$c['name'])?:'Customer';$initials=mb_strtoupper(mb_substr($name,0,1));$count=(int)$c['orders_count'];$joined=strtotime((string)$c['joined_at'])?:time();$active=(strtotime((string)$c['last_order_at'])?:0)>=time()-180*86400;$group=$count>1?'repeat':($joined>=time()-7*86400?'new':'');$cur=(string)($c['currency']??'USD');?><tr class="cus-row" data-status="<?=$active?'active':'inactive'?>" data-group="<?=org_ecommerce_h($group)?>" data-search="<?=org_ecommerce_h(mb_strtolower($cid.' '.$name.' '.(string)$c['email'].' '.(string)$c['phone']))?>"><td class="cus-id"><?=org_ecommerce_h($cid)?></td><td><div class="cus-person"><span class="cus-avatar"><?=org_ecommerce_h($initials)?></span><?=org_ecommerce_h($name)?></div></td><td><?=org_ecommerce_h((string)$c['email'])?></td><td><?=org_ecommerce_h((string)($c['phone']?:'—'))?></td><td><strong><?=$count?></strong></td><td><strong><?=org_ecommerce_h(org_sales_money((int)$c['spent_cents'],$cur))?></strong></td><td><?=org_ecommerce_h(org_sales_money($count?(int)round((int)$c['spent_cents']/$count):0,$cur))?></td><td><span class="cus-status <?=$active?'':'inactive'?>"><?=$active?'Active':'Inactive'?></span></td><td><?=org_ecommerce_h(date('M j, Y',$joined))?></td><td><a class="cus-more" href="crm_contacts.php" style="display:inline-flex;align-items:center;justify-content:center">•••</a></td></tr><?php endforeach;?></tbody></table></div><footer class="cus-foot"><span id="cusCount"><?=$total?> customers</span><div class="cus-pages" id="cusPages"></div><span>10 / page</span></footer></section></div>
<script>(function(){var root=document.getElementById('customersRoot'),rows=[].slice.call(root.querySelectorAll('.cus-row')),q=document.getElementById('cusSearch'),st=document.getElementById('cusStatus'),gr=document.getElementById('cusGroup'),page=1,size=10;function list(){var v=q.value.toLowerCase();return rows.filter(function(r){return(!v||r.dataset.search.indexOf(v)>-1)&&(!st.value||r.dataset.status===st.value)&&(!gr.value||r.dataset.group===gr.value)})}function draw(){var a=list(),pages=Math.max(1,Math.ceil(a.length/size));if(page>pages)page=pages;rows.forEach(function(r){r.hidden=true});a.slice((page-1)*size,page*size).forEach(function(r){r.hidden=false});document.getElementById('cusCount').textContent=a.length+' customers';var p=document.getElementById('cusPages');p.innerHTML='';for(var i=1;i<=pages;i++){var b=document.createElement('button');b.textContent=i;b.dataset.p=i;b.className=i===page?'on':'';b.onclick=function(){page=+this.dataset.p;draw()};p.appendChild(b)}}[q,st,gr].forEach(function(x){x.oninput=function(){page=1;draw()}});document.getElementById('cusReset').onclick=function(){q.value='';st.value='';gr.value='';page=1;draw()};document.getElementById('cusExport').onclick=function(){var lines=['Customer ID,Customer,Email,Phone,Orders,Spend,Average,Status,Joined'];list().forEach(function(r){lines.push([].slice.call(r.cells,0,9).map(function(c){return '"'+c.innerText.trim().replace(/"/g,'""')+'"'}).join(','))});var b=new Blob([lines.join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='customers.csv';a.click();setTimeout(function(){URL.revokeObjectURL(a.href)},500)};draw()})();</script>
